for (const item of $input.all()) {
  let parsed = {
    judul_topik: "Konten Simpul Sekolah",
    blog: {
      title: "Digitalisasi Sekolah Modern",
      slug: "digitalisasi-sekolah-modern",
      meta_description: "-",
      content_html: "<p>Artikel Simpul Sekolah</p>"
    },
    image_prompt: "A modern Indonesian teacher in a digital classroom, photorealistic, 8k",
    threads: [],
    facebook_post: "-",
    instagram: {
      carousel_slides: [],
      caption: "-",
      hashtags: "-"
    }
  };

  try {
    const rawText = item.json.text || item.json.output || item.json.response || "";
    const cleanJson = rawText.replace(/```json|```/gi, '').trim();
    parsed = JSON.parse(cleanJson);
  } catch (err) {
    parsed.judul_topik = "Gagal mem-parse output AI";
    parsed.facebook_post = item.json.text || "";
  }

  // Format preview Threads
  const threadsPreview = Array.isArray(parsed.threads)
    ? parsed.threads.map((t, idx) => `[Slide ${idx + 1}]\n${t}`).join("\n\n---\n\n")
    : "-";

  // Format preview Carousel IG
  const igSlidesPreview = Array.isArray(parsed.instagram?.carousel_slides)
    ? parsed.instagram.carousel_slides.map((s, idx) => `[Slide ${idx + 1}]\n${s}`).join("\n\n")
    : "-";

  // Generate URL Gambar AI Otomatis via Flux.1 (Resolusi 1080x1080)
  const encodedPrompt = encodeURIComponent(parsed.image_prompt || "indonesian school teacher tablet smart classroom");
  const aiImageUrl = `https://image.pollinations.ai/prompt/${encodedPrompt}?width=1080&height=1080&model=flux&nologo=true`;

   const uniqueId = `CNT-${Date.now()}-${Math.floor(Math.random() * 1000)}`;

  item.json = {
    id: uniqueId,
    tanggal_dibuat: new Date().toLocaleString("id-ID", { timeZone: "Asia/Jakarta" }),
    topik_utama: parsed.judul_topik || "Edukasi Digitalisasi Sekolah",
    // Data Blog (Siap dikirim ke API Simpul Sekolah)
    blog_payload: {
      title: parsed.blog?.title || parsed.judul_topik,
      slug: parsed.blog?.slug || "artikel-sekolah",
      meta_description: parsed.blog?.meta_description || "-",
      content: parsed.blog?.content_html || "",
      featured_image: aiImageUrl
    },
    // Data Media Sosial & Gambar
    image_url: aiImageUrl,
    image_prompt: parsed.image_prompt || "-",
    threads_content: threadsPreview,
    facebook_content: parsed.facebook_post || "-",
    instagram_content: `${igSlidesPreview}\n\n[CAPTION]\n${parsed.instagram?.caption || ""}\n\n[HASHTAGS]\n${parsed.instagram?.hashtags || ""}`,
    status: "DRAFT"
  };
}

return $input.all();
